//! 🎟️ Exact native page effects and retained scalar writes use the same neutral original-grant corpus.
use super::*;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn neutral_font_ledger_matches_scalar_reference_and_physical_admission(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut values=PagedList::<i64,{usize::MAX}>::new();let mut reference=Vec::new();for value in fixture["values"].as_array().unwrap(){let value=value.as_i64().unwrap();for turn in 0..100{let d=FontWorkLedger::slot_demand(&values).unwrap();let original=grant(d);let mut partials=vec![RetainedCloneGrant{maximum_items:0,..original},RetainedCloneGrant{maximum_depth:d.depth-1,..original}];if d.capacity_bytes>0{partials.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..original});}if d.copy_bytes>0{partials.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..original});}for partial in partials{let ((ready,receipt),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=FontWorkLedger::new(partial);let ready=work.slot(&mut values).unwrap();(ready,work.receipt())});assert!(!ready);assert_eq!(receipt.retained_capacity_bytes,0);assert_eq!(receipt.copied_bytes,0);assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);}let ((ready,receipt),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=FontWorkLedger::new(original);let ready=work.slot(&mut values).unwrap();if ready{work.push(&mut values,value).unwrap();}(ready,work.receipt())});assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,receipt.released_bytes);assert!(receipt.fits(original));if ready{reference.push(value);break;}assert!(turn<99);}}assert_eq!(values.iter().copied().collect::<Vec<_>>(),reference);semio_framework_2d_text_font_testing::close_with_items(values,1);}
#[test]fn unfinished_font_payload_holds_debit_only_committed_copies(){let mut first=PagedList::<i64,{usize::MAX}>::new();let mut second=PagedList::<i64,{usize::MAX}>::new();for values in [&mut first,&mut second]{while !values.has_reserved_slot(){let demand=FontWorkLedger::slot_demand(values).unwrap();let mut work=FontWorkLedger::new(grant(demand));assert!(!work.slot(values).unwrap());}}let mut partial=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1});assert!(partial.slot(&mut first).unwrap());assert!(!partial.slot(&mut second).unwrap());assert_eq!(partial.receipt().copied_bytes,0);assert_eq!(partial.next_demand().copy_bytes,16);let mut both=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1});assert!(both.slot(&mut first).unwrap());assert!(both.slot(&mut second).unwrap());both.push(&mut first,5).unwrap();both.push(&mut second,9).unwrap();assert_eq!(both.receipt().copied_bytes,16);assert_eq!(both.remaining().maximum_copy_bytes,0);semio_framework_2d_text_font_testing::close_with_items(first,1);semio_framework_2d_text_font_testing::close_with_items(second,1);}

#[test]fn neutral_contiguous_font_source_admission_preserves_original_allocation(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let target=fixture["materializationValues"].as_u64().unwrap()as usize;let mut values=Vec::<u64>::new();let bytes=target*std::mem::size_of::<u64>();let mut denied=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:bytes-1,maximum_release_bytes:0,maximum_depth:1});assert!(!denied.contiguous(&mut values,target).unwrap());assert_eq!(values.capacity(),0);assert_eq!(denied.receipt().retained_capacity_bytes,0);let(receipt,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1});assert!(!work.contiguous(&mut values,target).unwrap());work.receipt()});assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,0);assert_eq!(values.len(),0);assert_eq!(values.capacity(),target);semio_framework_2d_text_font_testing::close_with_items(values,1);}
